// Create your ModalConfig interface here
interface ModalConfig {
  id: string;
  title: string;
  content: string;
  isOpen?: boolean;
}

// Create your ModalManager class here
class ModalManager {
  private modals: ModalConfig[];

  constructor() {
    this.modals = [];
  }

  addModal(config: ModalConfig): void {
    this.modals.push({ ...config, isOpen: false });
  }

  openModal(id: string): void {
    const modal = this.modals.find(m => m.id === id);
    if (modal) {
      modal.isOpen = true;
    }
  }

  closeModal(id: string): void {
    const modal = this.modals.find(m => m.id === id);
    if (modal) {
      modal.isOpen = false;
    }
  }

  getModal(id: string): ModalConfig | undefined {
    return this.modals.find(m => m.id === id);
  }

  getAllModals(): ModalConfig[] {
    return [...this.modals];
  }

  // Add isModalConfig method here
}

// Create your demonstrateModalManager function here
function demonstrateModalManager() {
  const manager = new ModalManager();
  manager.addModal({ id: 'modal1', title: 'First Modal', content: 'Hello!' });
  manager.openModal('modal1');
  console.log(manager.getModal('modal1'));
  console.log(manager.getAllModals());
}

